import {ToolRegistry} from './registry.js';

describe('ToolRegistry dynamic validation', () => {
  it('reuses a dynamic schema without reading it again (spec: specs/hal-engine-tool-input-validation/spec.md#7)', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const schema = {
      get "'$id() {
        schemaReads += 1;
        return '"'https://example.com/weather';
      },
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    registry.register(
      () => ({name: 'weather', description: 'Weather for a location', inputSchema: schema}),
      async input => String(input.location)
    );
    await registry.execute('weather', {location: 'Berlin'});
    const readsAfterCompilation = schemaReads;

    const response = await registry.execute('weather', {location: 'Paris'});

    expect({response, schemaReads}).toEqual({response: {result: 'Paris'}, schemaReads: readsAfterCompilation});
  });
});
EOF
